pub fn supported(name: &str) -> bool {
    paths(name).is_some()
}

/// Only an enumerated, locally pinned icon is allowed; props never supply SVG.
pub(crate) fn render(name: &str, x: f32, y: f32, size: f32, color: &str) -> Node {
    let geometry = paths(name).unwrap_or_else(|| panic!("unsupported native icon {name}"));
    let shapes: Vec<Node> = geometry.iter().map(|d| draw::path(d).stroke(color, 2.0).round().node()).collect();
    draw::group(shapes).transform(skia_safe::Matrix::scale_translate((size / 24.0, size / 24.0), (x, y)))
}

#[cfg(test)]
mod tests {
    use super::*;
    #[test]
    fn only_named_trusted_icons_are_accepted() {
        assert!(supported("leaf"));
        assert!(supported("book-open"));
        assert!(!supported("../leaf.svg"));
        assert!(!supported("<svg><script>bad</script></svg>"));
    }
    #[test]
    fn pinned_geometry_draws_in_the_authored_colour() {
        let icon = render("leaf", 20.0, 40.0, 72.0, "#123456");
        let b = icon.bounds().expect("icon geometry");
        assert!(b.left >= 20.0 && b.top >= 40.0 && b.right <= 92.0 && b.bottom <= 112.0, "{b:?}");
        let crate::draw::Node::Group(g) = &icon else { panic!("a group") };
        let crate::draw::Node::Shape(s) = &g.children[0] else { panic!("a shape") };
        assert!(s.fill.is_none());
        assert!(
            matches!(s.stroke.as_ref().map(|s| &s.ink), Some(crate::draw::Ink::Color(c)) if (c.r - 0x12 as f32 / 255.0).abs() < 1e-3)
        );
    }
}
